1	/*
2	 * ESP32-S3 N10P 雷达数据无线转发固件
3	 *
4	 * Phase 2: UART 接收 + WiFi TCP 转发
5	 *   - Core 1: UART1 460800-8N1 接收 N10P 帧 → FreeRTOS 队列
6	 *   - Core 0: WiFi Station + TCP Server (port 8888) → 转发队列中的帧
7	 *
8	 * TCP 帧格式 (每帧 8+108=116 字节):
9	 *   [2B sync 0xA55A] [4B seq LE] [2B len LE] [108B N10P raw]
10	 *
11	 * 硬件连接:
12	 *   IO18 (UART1 RX) ← N10P CH9102 TX
13	 *   IO17 (UART1 TX) → N10P CH9102 RX (控制命令, 可选)
14	 *   GND ↔ GND
15	 */
16	
17	#include <stdio.h>
18	#include <string.h>
19	#include "freertos/FreeRTOS.h"
20	#include "freertos/task.h"
21	#include "freertos/queue.h"
22	#include "esp_system.h"
23	#include "esp_log.h"
24	#include "esp_timer.h"
25	#include "esp_wifi.h"
26	#include "esp_event.h"
27	#include "nvs_flash.h"
28	#include "driver/uart.h"
29	#include "lwip/sockets.h"
30	#include "lwip/netdb.h"
31	
32	static const char *TAG = "n10p_bridge";
33	
34	/* ============ WiFi 配置 (修改为你自己的路由器) ============ */
35	#define WIFI_SSID      "YLZ"
36	#define WIFI_PASS      "yy060315"
37	#define WIFI_MAX_RETRY 10
38	
39	/* ============ TCP Server 配置 ============ */
40	#define TCP_PORT        8888
41	#define TCP_LISTEN_BACKLOG 1
42	
43	/* ============ UART 配置 ============ */
44	#define UART_PORT       UART_NUM_1
45	#define UART_TX_PIN     17
46	#define UART_RX_PIN     18
47	#define UART_BAUD_RATE  460800
48	#define UART_BUF_SIZE   (108 * 20)
49	
50	/* ============ N10P 帧参数 ============ */
51	#define N10P_FRAME_SIZE     108
52	#define N10P_FRAME_HEADER0  0xA5
53	#define N10P_FRAME_HEADER1  0x5A
54	
55	/* TCP 直接发送 N10P 原始帧 (无额外包装), lslidar_driver 自带帧同步 */
56	
57	/* ============ 队列 ============ */
58	#define FRAME_QUEUE_LEN 32
59	static QueueHandle_t g_frame_queue;
60	
61	/* ============ 统计 ============ */
62	static uint32_t g_total_frames   = 0;
63	static uint32_t g_valid_frames   = 0;
64	static uint32_t g_tcp_sent       = 0;
65	static int64_t  g_last_report_us = 0;
66	
67	/* ---- CRC8 ---- */
68	static uint8_t n10p_crc8(const uint8_t *data, int len) {
69	    int sum = 0;
70	    for (int i = 0; i < len; i++) sum += data[i];
71	    return (uint8_t)(sum & 0xFF);
72	}
73	
74	/* ---- UART 初始化 ---- */
75	static void uart_init(void) {
76	    uart_config_t cfg = {
77	        .baud_rate  = UART_BAUD_RATE,
78	        .data_bits  = UART_DATA_8_BITS,
79	        .parity     = UART_PARITY_DISABLE,
80	        .stop_bits  = UART_STOP_BITS_1,
81	        .flow_ctrl  = UART_HW_FLOWCTRL_DISABLE,
82	        .source_clk = UART_SCLK_DEFAULT,
83	    };
84	    ESP_ERROR_CHECK(uart_driver_install(UART_PORT, UART_BUF_SIZE, 0, 0, NULL, 0));
85	    ESP_ERROR_CHECK(uart_param_config(UART_PORT, &cfg));
86	    ESP_ERROR_CHECK(uart_set_pin(UART_PORT, UART_TX_PIN, UART_RX_PIN,
87	                                 UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE));
88	    ESP_ERROR_CHECK(uart_set_rx_timeout(UART_PORT, 3));
89	    ESP_LOGI(TAG, "UART1 init OK: %d-8N1, RX=IO%d TX=IO%d",
90	             UART_BAUD_RATE, UART_RX_PIN, UART_TX_PIN);
91	}
92	
93	/* ====================================================================
94	 * Core 1: UART 帧接收任务 (同 Phase 1, 但收帧后推入队列)
95	 * ==================================================================== */
96	typedef enum { ST_WAIT_H0, ST_WAIT_H1, ST_COLLECT } fsm_state_t;
97	
98	static void uart_rx_task(void *arg) {
99	    uint8_t buf[256];
100	    uint8_t frame[N10P_FRAME_SIZE];
101	    int     idx = 0;
102	    fsm_state_t st = ST_WAIT_H0;
103	
104	    while (1) {
105	        int len = uart_read_bytes(UART_PORT, buf, sizeof(buf), pdMS_TO_TICKS(10));
106	        if (len <= 0) continue;
107	
108	        for (int i = 0; i < len; i++) {
109	            uint8_t b = buf[i];
110	            switch (st) {
111	            case ST_WAIT_H0:
112	                if (b == N10P_FRAME_HEADER0) { frame[0] = b; st = ST_WAIT_H1; }
113	                break;
114	            case ST_WAIT_H1:
115	                if (b == N10P_FRAME_HEADER1) { frame[1] = b; idx = 2; st = ST_COLLECT; }
116	                else if (b == N10P_FRAME_HEADER0) { frame[0] = b; }
117	                else { st = ST_WAIT_H0; }
118	                break;
119	            case ST_COLLECT:
120	                frame[idx++] = b;
121	                if (idx >= N10P_FRAME_SIZE) {
122	                    g_total_frames++;
123	                    uint8_t crc = n10p_crc8(frame, N10P_FRAME_SIZE - 1);
124	                    if (frame[N10P_FRAME_SIZE - 1] == crc) {
125	                        g_valid_frames++;
126	                        /* 有效帧推入队列 (非阻塞, 满了就丢) */
127	                        uint8_t *copy = malloc(N10P_FRAME_SIZE);
128	                        if (copy) {
129	                            memcpy(copy, frame, N10P_FRAME_SIZE);
130	                            if (xQueueSend(g_frame_queue, &copy, 0) != pdTRUE) {
131	                                free(copy);
132	                            }
133	                        }
134	                    }
135	                    st = ST_WAIT_H0;
136	                }
137	                break;
138	            }
139	        }
140	
141	        /* 每秒统计 */
142	        int64_t now = esp_timer_get_time();
143	        if (now - g_last_report_us > 1000000) {
144	            float secs = (now - g_last_report_us) / 1000000.0f;
145	            ESP_LOGI(TAG, "UART: total=%lu valid=%lu (%.0ffps) TCP发送=%lu 队列剩余=%d",
146	                     g_total_frames, g_valid_frames,
147	                     g_valid_frames / secs, g_tcp_sent,
148	                     (int)uxQueueMessagesWaiting(g_frame_queue));
149	            g_total_frames = 0;
150	            g_valid_frames = 0;
151	            g_tcp_sent    = 0;
152	            g_last_report_us = now;
153	        }
154	    }
155	}
