157	/* ====================================================================
158	 * Core 0: TCP Server 任务
159	 * ==================================================================== */
160	static void tcp_server_task(void *arg) {
161	    int listen_sock, client_sock = -1;
162	    struct sockaddr_in server_addr, client_addr;
163	    socklen_t addr_len = sizeof(client_addr);
164	
165	    while (1) {
166	        /* 创建监听 socket */
167	        listen_sock = socket(AF_INET, SOCK_STREAM, 0);
168	        if (listen_sock < 0) {
169	            ESP_LOGE(TAG, "socket failed: %d", errno);
170	            vTaskDelay(pdMS_TO_TICKS(2000));
171	            continue;
172	        }
173	
174	        int opt = 1;
175	        setsockopt(listen_sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
176	
177	        memset(&server_addr, 0, sizeof(server_addr));
178	        server_addr.sin_family = AF_INET;
179	        server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
180	        server_addr.sin_port = htons(TCP_PORT);
181	
182	        if (bind(listen_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
183	            ESP_LOGE(TAG, "bind failed: %d", errno);
184	            close(listen_sock);
185	            vTaskDelay(pdMS_TO_TICKS(2000));
186	            continue;
187	        }
188	
189	        if (listen(listen_sock, TCP_LISTEN_BACKLOG) < 0) {
190	            ESP_LOGE(TAG, "listen failed: %d", errno);
191	            close(listen_sock);
192	            vTaskDelay(pdMS_TO_TICKS(2000));
193	            continue;
194	        }
195	
196	        ESP_LOGI(TAG, "TCP Server 监听端口 %d, 等待客户端连接...", TCP_PORT);
197	
198	        /* 接受客户端连接 */
199	        client_sock = accept(listen_sock, (struct sockaddr *)&client_addr, &addr_len);
200	        if (client_sock < 0) {
201	            ESP_LOGE(TAG, "accept failed: %d", errno);
202	            close(listen_sock);
203	            vTaskDelay(pdMS_TO_TICKS(2000));
204	            continue;
205	        }
206	
207	        ESP_LOGI(TAG, "客户端已连接! 开始转发数据...");
208	        close(listen_sock);  /* 只接受一个连接 */
209	
210	        /* 转发循环: 队列取帧 → 直接发送 108 字节原始 N10P 帧 */
211	        uint8_t *frame;
212	        while (1) {
213	            if (xQueueReceive(g_frame_queue, &frame, pdMS_TO_TICKS(1000)) != pdTRUE) {
214	                continue;
215	            }
216	
217	            /* 直接发送 N10P 原始帧 (TCP 流式传输, lslidar_driver 做帧同步) */
218	            int sent = send(client_sock, frame, N10P_FRAME_SIZE, 0);
219	            free(frame);
220	            if (sent <= 0) {
221	                ESP_LOGW(TAG, "客户端断开 (sent=%d errno=%d)", sent, errno);
222	                free(frame);  /* 这帧丢弃 */
223	                break;
224	            }
225	            g_tcp_sent++;
226	        }
227	
228	        /* 客户端断开, 清理 */
229	        close(client_sock);
230	        client_sock = -1;
231	        ESP_LOGI(TAG, "等待新客户端连接...");
232	    }
233	}
