235	/* ====================================================================
236	 * WiFi 事件回调
237	 * ==================================================================== */
238	static int g_wifi_retry = 0;
239	static EventGroupHandle_t g_wifi_event_group;
240	#define WIFI_CONNECTED_BIT BIT0
241	#define WIFI_FAIL_BIT      BIT1
242	
243	static void wifi_event_handler(void *arg, esp_event_base_t base,
244	                               int32_t id, void *data) {
245	    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
246	        esp_wifi_connect();
247	    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
248	        if (g_wifi_retry < WIFI_MAX_RETRY) {
249	            esp_wifi_connect();
250	            g_wifi_retry++;
251	            ESP_LOGW(TAG, "WiFi 断连, 重试 %d/%d", g_wifi_retry, WIFI_MAX_RETRY);
252	        } else {
253	            xEventGroupSetBits(g_wifi_event_group, WIFI_FAIL_BIT);
254	        }
255	    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
256	        ip_event_got_ip_t *ev = (ip_event_got_ip_t *)data;
257	        ESP_LOGI(TAG, "WiFi 已连接! IP: " IPSTR, IP2STR(&ev->ip_info.ip));
258	        g_wifi_retry = 0;
259	        xEventGroupSetBits(g_wifi_event_group, WIFI_CONNECTED_BIT);
260	    }
261	}
262	
263	static void wifi_init_sta(void) {
264	    g_wifi_event_group = xEventGroupCreate();
265	    ESP_ERROR_CHECK(esp_netif_init());
266	    ESP_ERROR_CHECK(esp_event_loop_create_default());
267	    esp_netif_create_default_wifi_sta();
268	
269	    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
270	    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
271	
272	    esp_event_handler_instance_t inst_any_id, inst_got_ip;
273	    ESP_ERROR_CHECK(esp_event_handler_instance_register(
274	        WIFI_EVENT, ESP_EVENT_ANY_ID, &wifi_event_handler, NULL, &inst_any_id));
275	    ESP_ERROR_CHECK(esp_event_handler_instance_register(
276	        IP_EVENT, IP_EVENT_STA_GOT_IP, &wifi_event_handler, NULL, &inst_got_ip));
277	
278	    wifi_config_t wifi_cfg = {
279	        .sta = {
280	            .ssid = WIFI_SSID,
281	            .password = WIFI_PASS,
282	            .threshold.authmode = WIFI_AUTH_WPA2_PSK,
283	        },
284	    };
285	    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
286	    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg));
287	    ESP_ERROR_CHECK(esp_wifi_start());
288	
289	    ESP_LOGI(TAG, "WiFi Station 启动, 连接 SSID: %s", WIFI_SSID);
290	
291	    EventBits_t bits = xEventGroupWaitBits(g_wifi_event_group,
292	        WIFI_CONNECTED_BIT | WIFI_FAIL_BIT, pdFALSE, pdFALSE, portMAX_DELAY);
293	    if (bits & WIFI_CONNECTED_BIT) {
294	        ESP_LOGI(TAG, "WiFi 连接成功!");
295	    } else {
296	        ESP_LOGE(TAG, "WiFi 连接失败!");
297	    }
298	}
299	
300	/* ====================================================================
301	 * 主入口
302	 * ==================================================================== */
303	void app_main(void) {
304	    esp_err_t ret = nvs_flash_init();
305	    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
306	        ESP_ERROR_CHECK(nvs_flash_erase());
307	        ESP_ERROR_CHECK(nvs_flash_init());
308	    }
309	
310	    ESP_LOGI(TAG, "=== N10P 雷达 WiFi 无线转发固件 v4 ===");
311	    ESP_LOGI(TAG, "Phase 3: UART → WiFi TCP 原始帧转发 (无包装)");
312	    ESP_LOGI(TAG, "硬件: ESP32-S3 N16R8, UART1 RX=IO%d, %d-8N1",
313	             UART_RX_PIN, UART_BAUD_RATE);
314	
315	    /* 初始化队列 */
316	    g_frame_queue = xQueueCreate(FRAME_QUEUE_LEN, sizeof(uint8_t *));
317	    assert(g_frame_queue != NULL);
318	
319	    /* 初始化 UART */
320	    uart_init();
321	
322	    /* 连接 WiFi (阻塞, 连接成功后才继续) */
323	    wifi_init_sta();
324	
325	    /* 启动 TCP Server (Core 0, lwIP 默认在此核) */
326	    xTaskCreate(tcp_server_task, "tcp_srv", 4096, NULL, 5, NULL);
327	
328	    /* 启动 UART 接收任务 (Core 1, WiFi 协议栈不占用) */
329	    xTaskCreatePinnedToCore(uart_rx_task, "uart_rx", 4096, NULL, 10, NULL, 1);
330	
331	    ESP_LOGI(TAG, "=== 系统就绪 === 等待雷达数据和客户端连接...");
332	}
